contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, C.MerkleMultiProof calldata proof, uint256 amount) public payable {
        require(tokenIds.length > 0 && amount > 0, "bad input");
        require(c.baseToken() == address(0), "not ETH pool");
        require(address(this).balance >= amount, "insufficient balance");
        require(!c.useStolenNftOracle(), "stolen oracle unsupported");

        uint256 beforeBase = c.virtualBaseTokenReserves();
        uint256 beforeNft = c.virtualNftReserves();

        // Read-only quote to know the required input without changing state.
        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);
        (uint256 netInput, , ) = c.buyQuote(weightSum);
        require(amount >= netInput, "insufficient eth amount");

        bool reverted;
        try c.buy{value: amount}(tokenIds, tokenWeights, proof) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // A successful buy must never decrease the pool's virtual base reserves.
            assert(c.virtualBaseTokenReserves() >= beforeBase);
            // And it must increase them whenever the pool had positive virtual NFT reserves.
            if (beforeNft > 0) {
                assert(c.virtualBaseTokenReserves() > beforeBase);
            }
        } else {
            // A reverted buy must leave reserves untouched.
            assert(c.virtualBaseTokenReserves() == beforeBase);
        }
    }

    receive() external payable {}
}

