contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(c.baseToken() == address(0), "not ETH pool");
        require(c.merkleRoot() == bytes32(0), "merkle root required");
        require(!c.useStolenNftOracle(), "stolen oracle unsupported");
        require(!c.payRoyalties(), "royalties unsupported");
        require(amount > 0, "zero amount");
        require(amount < 1 ether, "too large");
        require(address(this).balance >= amount, "insufficient balance");

        uint256[] memory ids = new uint256[](0);
        uint256[] memory weights = new uint256[](0);
        C.MerkleMultiProof memory proof = C.MerkleMultiProof(new bytes32[](0), new bool[](0));

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(0);

        uint256 beforeBase = c.virtualBaseTokenReserves();
        uint256 beforeNft = c.virtualNftReserves();

        bool reverted;
        try c.buy{value: amount}(ids, weights, proof) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(amount < netInputAmount);
        } else {
            assert(amount == netInputAmount);
            assert(c.virtualBaseTokenReserves() == beforeBase + (netInputAmount - feeAmount - protocolFeeAmount));
            assert(c.virtualNftReserves() == beforeNft);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
