    }

    function run(uint16 newFeeRate, bool newPayRoyalties) public {
        require(newFeeRate <= 5000);

        c.setFeeRate(newFeeRate);
        uint16 feeRateAfter = c.feeRate();

        c.setPayRoyalties(newPayRoyalties);
        bool payRoyaltiesAfter = c.payRoyalties();

        assert(feeRateAfter == newFeeRate && payRoyaltiesAfter == newPayRoyalties);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        require(feeRate <= 5000, "feeRate too high");
        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        assert(
            c.initialized() &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == virtualBaseTokenReserves &&
            c.virtualNftReserves() == virtualNftReserves &&
            c.changeFee() == changeFee &&
            c.feeRate() == feeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useStolenNftOracle &&
            c.payRoyalties() == payRoyalties
        );
    }

    receive() external payable {}
}
